/* Aroma clinic workspace. SmartAdmin 4.4.1 assets, Laravel session API. */
(() => {
    'use strict';
    const $ = s => document.querySelector(s);
    const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const title = value => String(value ?? '').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    const icon = name => `<i class="fas fa-${esc(name)}" aria-hidden="true"></i>`;
    const initial = name => String(name || '').split(' ').map(n => n[0]).slice(0,2).join('');
    const dateOnly = d => { const x = d || new Date(); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
    const dateTime = value => value ? String(value).replace(' ', 'T').slice(0,16) : `${dateOnly()}T09:00`;
    let boot, current = '', rows = [], page = 1, search = '', navigationId = 0, calendar = null, bookingOptions;
    const csrf = $('meta[name="csrf-token"]').content;
    const money = cents => new Intl.NumberFormat('en-CA', {style:'currency',currency:boot?.settings.currency || 'CAD'}).format(Number(cents || 0)/100);
    const badge = status => `<span class="status-pill status-${esc(status)}">${esc(title(status))}</span>`;
    async function api(path, options = {}) {
        const form = options.body instanceof FormData;
        const response = await fetch('/api/' + path, {...options, headers: {'Accept':'application/json','X-CSRF-TOKEN':csrf,...(boot?.selected_branch?{'X-Clinic-Branch':String(boot.selected_branch)}:{}),...(!form && options.body ? {'Content-Type':'application/json'} : {}),...options.headers}});
        if (response.status === 401 || response.status === 419) { location.href = '/login'; throw new Error('Session expired. Please sign in again.'); }
        const data = await response.json().catch(() => ({}));
        if (!response.ok) { const error = new Error(Object.values(data.errors || {}).flat().join('\n') || data.message || 'Unable to complete this request.'); error.details = data.errors; throw error; }
        return data;
    }
    function toast(message, error = false) { const el=document.createElement('div');el.className='toast-note'+(error?' error':'');el.textContent=message;$('#toast-region').append(el);setTimeout(()=>el.remove(),6000); }
    function empty(message = 'Your next record starts here.', detail = 'Add a record to keep your clinic connected.') { return `<div class="empty-state">${icon('seedling')}<h3>${esc(message)}</h3><p>${esc(detail)}</p></div>`; }
    function heading(name, description, button = '') { return `<div class="page-heading"><div><span class="eyebrow">${esc(boot.settings.clinic_name)} / WORKSPACE</span><h1>${esc(name)}</h1><p>${esc(description)}</p></div><div class="heading-actions">${button}</div></div>`; }
    function newButton(module, label = 'Add record') { return boot.modules[module]?.can_create ? `<button class="btn btn-primary" data-new="${esc(module)}">${icon('plus')} ${esc(label)}</button>` : ''; }
    function panel(name, sub, content, action = '') { return `<section class="panel"><div class="panel-heading"><div><h2>${esc(name)}</h2><p>${esc(sub)}</p></div>${action}</div>${content}</section>`; }
    function navHtml(items, depth = 0) {
        return items.map(item => {
            if (!item.module && depth === 0) return `<div class="nav-group"><div class="nav-heading">${esc(item.label)}</div>${navHtml(item.children,1)}</div>`;
            return `<div class="nav-item"><div class="nav-row" data-nav="${esc(item.module || '')}">${item.module ? `<a href="/admin/${esc(item.module)}" data-route="${esc(item.module)}">${icon(item.icon)}<span>${esc(item.label)}</span></a>` : `<button class="nav-parent" data-expand="nav-${item.id}">${icon(item.icon)}${esc(item.label)}</button>`}${item.children.length ? `<button class="nav-expand" aria-label="Expand ${esc(item.label)}" aria-expanded="false" data-expand="nav-${item.id}">${icon('angle-down')}</button>` : ''}</div>${item.children.length ? `<div id="nav-${item.id}" class="nav-children" hidden>${navHtml(item.children,depth+1)}</div>` : ''}</div>`;
        }).join('');
    }
    async function refreshBootstrap() {
        boot = await api('bootstrap');window.ClinicTheme.apply(boot.theme);$('#navigation').innerHTML=navHtml(boot.menu);$('#profile-name').textContent=boot.user.name;$('#profile-role').textContent=boot.user.role;
        document.querySelectorAll('.avatar:not(.client-avatar)').forEach(el=>el.textContent=initial(boot.user.name));
        $('#clinic-location').textContent=boot.settings.location;$('#clinic-currency').textContent=`${boot.settings.currency} · Clinic workspace`;$('#footer-timezone').textContent=boot.settings.timezone;
        $('#today-label').textContent=new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeZone:boot.settings.timezone}).format(new Date());
        $('#branch-selector').innerHTML=(boot.user.is_org_owner?'<option value="all">All branches · Combined view</option>':'')+boot.branches.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('');
        $('#branch-selector').value=String(boot.selected_branch);
        document.querySelectorAll('a[href^="/book"]').forEach(link=>link.href=boot.booking_url);
    }
    async function navigate(module, push = true) {
        const run=++navigationId;current=module;page=1;search='';if(calendar){calendar.destroy();calendar=null;}
        if(push)history.pushState({module},'',`/admin/${module}`);
        document.body.classList.remove('sidebar-open');window.scrollTo(0,0);document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===module));
        const active=document.querySelector(`[data-nav="${CSS.escape(module)}"]`);let parent=active?.closest('.nav-children');while(parent){parent.hidden=false;parent=parent.parentElement.closest('.nav-children');}
        $('#breadcrumb').textContent=boot.modules[module]?.title || ({dashboard:'Overview',reports:'Reports & insights',settings:'Clinic settings',branches:'Organization & branches'}[module] || 'Workspace');
        $('#content').innerHTML='<div class="loading-state"><span class="spinner-border"></span><p>Loading your workspace…</p></div>';
        try {
            if(module==='dashboard') await dashboard(run);
            else if(module==='appointments') await calendarPage(run);
            else if(module==='roles') await rolesPage(run);
            else if(module==='reports') await reportsPage(run);
            else if(module==='settings') await settingsPage(run);
            else if(module==='branches'&&boot.user.is_org_owner) await branchesPage(run);
            else if(boot.modules[module]) await listPage(run);
            else $('#content').innerHTML=empty('This module is not available.','Your role may not have access. Choose a section from the sidebar.');
        }catch(error){if(run===navigationId)$('#content').innerHTML=empty('Unable to load this section.',error.message);}
    }
    async function dashboard(run) {
        const d=await api('dashboard');if(run!==navigationId)return;
        if(d.aggregate){aggregateDashboard(d);return;}
        const stat=(label,value,note,ico,tone='')=>`<article class="stat-card ${tone}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${note}</div></article>`;
        let stats='';if('appointments'in d.stats)stats+=stat('Appointments today',d.stats.appointments,`${d.stats.completed} completed · Your day, organized`,'calendar-alt');if('collected_cents'in d.stats)stats+=stat('Collected today',money(d.stats.collected_cents),'From your payment ledger','credit-card','lilac');if('clients'in d.stats)stats+=stat('Active clients',d.stats.clients,'Every client. One connected profile.','users','sand');if('outstanding_cents'in d.stats)stats+=stat('Outstanding balance',money(d.stats.outstanding_cents),'Across all open invoices','wallet','sage');
        const bookings=d.appointments.length ? `<div class="table-responsive"><table class="table"><thead><tr><th>Time</th><th>Client & treatment</th><th>Practitioner</th><th>Status</th><th></th></tr></thead><tbody>${d.appointments.map(a=>`<tr><td><strong>${esc(a.starts_at.slice(11,16))}</strong><small>${a.duration} min</small></td><td><div class="client-cell"><span class="avatar client-avatar">${esc(initial(a.client))}</span><span><strong>${esc(a.client)}</strong><small>${esc(a.service)}</small></span></div></td><td>${esc(a.practitioner)}</td><td>${badge(a.status)}</td><td><button class="icon-button" data-booking="${a.id}" aria-label="Open appointment">${icon('arrow-right')}</button></td></tr>`).join('')}</tbody></table></div>` : empty('A little breathing room.','No appointments scheduled for today.');
        const max=Math.max(1,...d.week.map(x=>x.count));
        const week=panel('Your week in appointments','A little perspective on the care you provide.',`<div class="chart-area" role="img" aria-label="${esc(d.week.map(x=>`${x.day}: ${x.count}`).join(', '))}">${d.week.map(x=>`<div class="chart-col"><b>${x.count}</b><div class="chart-bar" style="height:${Math.max(4,x.count/max*95)}px"></div><span>${esc(x.day)}</span></div>`).join('')}</div>`,'<span class="muted" style="font-size:10px">LAST 7 DAYS</span>');
        const tasks=d.tasks.map(t=>`<div class="task-item"><span class="task-circle">${icon('circle')}</span><div><strong>${esc(t.title)}</strong><small>${esc(t.due_on)} · ${esc(title(t.priority))}</small></div></div>`).join('');
        $('#content').innerHTML=heading('A beautiful day to care.','Everything you need for a thoughtful, well-run clinic.',newButton('appointments','New appointment'))+`<div class="stats-grid">${stats}</div><div class="dashboard-grid"><div>${boot.modules.appointments?panel('Today’s appointments','A little preparation. A seamless visit.',bookings+`<div class="table-footer"><span>${d.appointments.length} visits on today’s calendar</span><span>All times in ${esc(boot.settings.timezone)}</span></div>`,'<a href="/admin/appointments" data-route="appointments">Open calendar →</a>'):''}${d.week.length?week:''}</div><div class="dashboard-side"><section class="care-card"><span class="eyebrow">THE LITTLE THINGS MATTER</span><h2>A personal touch<br>makes all the difference.</h2><p>More time for your clients.<br>More room for great care.</p></section>${boot.modules.tasks?panel('On your radar','The next things that need a little care.',`<div class="task-list">${tasks || '<div class="task-item">You’re all caught up.</div>'}</div>${d.low_stock.length?`<div class="low-stock">${icon('box-open')} ${d.low_stock.length} products need a stock review</div>`:''}`,'<a href="/admin/tasks" data-route="tasks">All tasks →</a>'):''}</div></div>${d.services.length?panel('Care, in every form','Your active services, ready for the next visit.',`<div class="panel-body service-list">${d.services.map(s=>`<a class="service-tile" href="/admin/services" data-route="services">${icon('spa')}<strong>${esc(s.name)}</strong><small>${s.duration} min · ${money(s.price_cents)}</small></a>`).join('')}</div>`,'<a href="/admin/services" data-route="services">Service menu →</a>'):''}`;
        rows=d.appointments;
    }
    function subnav(module) { return `<div class="subnav">${Object.entries(boot.modules).filter(([,d])=>d.parent===module).map(([k,d])=>`<a href="/admin/${k}" data-route="${k}">${esc(d.title)}</a>`).join('')}</div>`; }
    function display(row,key,definition={}) {
        if(key.endsWith('_cents'))return esc(new Intl.NumberFormat('en-CA',{style:'currency',currency:row.currency||boot.settings.currency}).format(Number(row[key]||0)/100));
        if(key==='status'||key==='priority')return badge(row[key]);
        if(key==='photo')return `<a href="/api/photos/${row.id}/file" target="_blank" rel="noopener">Open private file ↗</a>`;
        if(row[key+'_label'])return esc(row[key+'_label']);
        if(definition.fields?.[key]?.type==='checkbox'||typeof row[key]==='boolean')return row[key]?'Yes':'No';
        if(Array.isArray(row[key]))return esc(row[key].join(', '));
        return esc(row[key]??'—');
    }
    function columns(module) {
        const custom={invoices:['number','client_id','total_cents','paid_cents','balance_cents','status'],client_packages:['client_id','package_id','sessions_total','sessions_used','expires_on'],products:['name','sku','price_cents','stock','reorder_level','status'],appointments:['starts_at','client_id','service_id','staff_id','status'],treatment_records:['appointment_id','assessment','follow_up_on','status'],consents:['client_id','appointment_id','form_template_id','signed_name','signed_at'],stock_movements:['product_id','quantity','reason','batch','expires_on'],message_outbox:['client_id','channel','subject','status','created_at'],audit_logs:['user_id','action','entity','entity_id','created_at'],memberships:['client_id','membership_plan_id','starts_on','expires_on','status'],photos:['client_id','caption','stage','taken_on','photo'],campaigns:['name','channel','audience','scheduled_at','status'],services:['name','category_id','duration','price_cents','status'],staff:['name','specialty','starts_at','ends_at','status']};
        return custom[module] || Object.keys(boot.modules[module].fields).filter(k=>!['password','content','body','notes','description','benefits','staff_ids'].includes(k)).slice(0,5);
    }
    function rowActions(module,row) {
        let html=`<button class="btn btn-light btn-sm" data-detail="${row.id}">View</button>`;const d=boot.modules[module];
        if(module==='invoices')return `<button class="btn btn-light btn-sm" data-invoice="${row.id}">Invoice</button>${d.can_edit?` <button class="btn btn-primary btn-sm" data-payment="${row.id}">Payment</button>`:''}`;
        if(module==='clients')html=`<button class="btn btn-light btn-sm" data-client="${row.id}">Profile</button>`;
        if(d.can_edit&&!d.immutable&&!d.readonly&&!(module==='treatment_records'&&row.status==='finalized')&&!(module==='users'&&row.is_org_owner))html+=` <button class="icon-button" data-edit="${row.id}" aria-label="Edit record">${icon('pen')}</button>`;
        if(module==='campaigns'&&d.can_edit&&row.status==='draft')html+=` <button class="btn btn-light btn-sm" data-prepare="${row.id}">Prepare</button>`;
        if(module==='leads'&&d.can_edit&&boot.modules.clients?.can_create&&!row.client_id)html+=` <button class="btn btn-light btn-sm" data-convert="${row.id}">Convert</button>`;
        if(module==='waitlist'&&boot.modules.appointments?.can_create&&['waiting','contacted'].includes(row.status))html+=` <button class="btn btn-light btn-sm" data-waitlist="${row.id}">Book visit</button>`;
        return html;
    }
    async function listPage(run = navigationId) {
        const module=current,d=boot.modules[module];
        $('#content').innerHTML=heading(d.title,({clients:'One connected record for every client.',services:'Your treatments, timing, pricing and eligible practitioners.',products:'Know what’s in stock. Keep every movement accounted for.',invoices:'Connected invoices, payments and outstanding balances.',treatment_records:'Document care, preserve history, and follow through.',menu_items:'A permission-aware navigation tree, organized your way.'}[module] || 'Connected records. Clear history. Everything in its place.'),!d.readonly?newButton(module,module==='invoices'?'Create invoice':'Add '+(module==='clients'?'client':'record')):'')+subnav(module)+(module==='campaigns'||module==='message_outbox'?'<div class="note-banner">Messages are prepared locally. Email, SMS and WhatsApp delivery require a connected provider.</div>':'')+`<div class="toolbar"><input id="record-search" class="form-control toolbar-search" type="search" placeholder="Search ${esc(d.title.toLowerCase())}…" value="${esc(search)}" aria-label="Search records"><span class="muted" id="result-count"></span></div><section class="panel" id="record-list"><div class="loading-state">Loading records…</div></section>`;
        await loadRows(run);
    }
    async function loadRows(run = navigationId) {
        const module=current;const result=await api(`modules/${module}?page=${page}&search=${encodeURIComponent(search)}`);if(run!==navigationId||module!==current)return;rows=result.rows;
        $('#result-count').textContent=`${result.total} records`;const d=boot.modules[module], cols=columns(module);
        $('#record-list').innerHTML=(rows.length?`<div class="table-responsive"><table class="table"><thead><tr>${cols.map(k=>`<th>${esc(d.fields[k]?.label||title(k.replace(/_cents$/,'').replace(/_id$/,'')))}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(k=>`<td>${display(r,k,d)}</td>`).join('')}<td style="white-space:nowrap">${rowActions(module,r)}</td></tr>`).join('')}</tbody></table></div>`:empty())+`<div class="table-footer"><span>Page ${result.page} of ${result.last_page}</span><div><button class="btn btn-light btn-sm" data-page="${page-1}" ${page<=1?'disabled':''}>← Previous</button> <button class="btn btn-light btn-sm" data-page="${page+1}" ${page>=result.last_page?'disabled':''}>Next →</button></div></div>`;
    }
    function openDialog(name,html) { $('#editor-title').textContent=name;$('#editor-body').innerHTML=html;if(!$('#editor').open)$('#editor').showModal();$('#editor-body').scrollTop=0; }
    function closeDialog() { $('#editor').close(); }
    function formFooter(label='Save record') { return `<div class="form-actions"><button type="button" class="btn btn-light" data-close>Cancel</button><button class="btn btn-primary" type="submit">${esc(label)} →</button></div>`; }
    function detailHtml(record, definition = {}) {
        return `<div class="detail-grid">${Object.entries(record).filter(([k])=>!k.endsWith('_label')&&!['path','request_id','password','remember_token','staff_ids'].includes(k)).map(([k,v])=>`<div class="detail-item"><small>${esc(definition.fields?.[k]?.label||title(k.replace(/_cents$/,'').replace(/_id$/,'')))}</small><span>${display(record,k,definition)}</span></div>`).join('')}</div>`;
    }
    function fieldHtml(key, field, value) {
        const required=field.rules.includes('required')||field.rules.includes('accepted'), type=field.type;let input='',attributes=`name="${key}" id="field-${key}" ${required?'required':''}`;
        if(type==='checkbox')return `<label class="check-label"><input type="checkbox" ${attributes} value="1" ${value?'checked':''}>${esc(field.label)}</label>`;
        if(type==='textarea')input=`<textarea class="form-control" ${attributes}>${esc(value||'')}</textarea>`;
        else if(type==='reference'||type==='multireference')input=`<input class="form-control reference-search" type="search" placeholder="Search options…" data-reference="${key}" aria-label="Search ${esc(field.label)}"><select class="form-control" ${attributes} ${type==='multireference'?'multiple size="4"':''}><option value="">Select…</option></select>`;
        else if(type==='select'||type==='multiselect')input=`<select class="form-control" ${attributes} ${type==='multiselect'?'multiple size="4"':''}>${field.options.map(option=>`<option value="${esc(option)}" ${(Array.isArray(value)?value.map(String).includes(String(option)):String(value)===String(option))?'selected':''}>${esc(title(option))}</option>`).join('')}</select>`;
        else { if(type==='money'&&value!==undefined)value=Number(value)/100;if(type==='datetime-local')value=value?dateTime(value):(required?dateTime():'');if(type==='time'&&value)value=String(value).slice(0,5);if(type==='password')value='';input=`<input class="form-control" ${attributes} type="${type==='money'?'number':type}" ${type==='money'?'step="0.01" min="0"':''} ${type==='file'?'accept="image/jpeg,image/png,image/webp,application/pdf"':`value="${esc(value??(type==='color'?'#739d92':''))}"`}>`; }
        return `<label class="${type==='textarea'?'full':''}" for="field-${key}">${esc(field.label)}${required?' <span class="muted">*</span>':''}${input}</label>`;
    }
    async function fillReference(module,key,value,term='') {
        const select=$(`#field-${key}`);if(!select)return;const choices=await api(`modules/${module}/lookup/${key}?search=${encodeURIComponent(term)}&ids=${encodeURIComponent([value].flat().filter(Boolean).join(','))}`);if(!select.isConnected)return;
        const selected=Array.isArray(value)?value.map(String):[String(value??'')];select.innerHTML=(!select.multiple?'<option value="">Select…</option>':'')+choices.map(o=>`<option value="${o.id}" ${selected.includes(String(o.id))?'selected':''}>${esc(o.label)}</option>`).join('');
    }
    async function editRecord(module,record={},defaults={}) {
        if(module==='invoices')return invoiceForm();if(module==='roles')return roleForm();
        const d=boot.modules[module];if(!d)throw new Error('You do not have access to this module.');
        const values={status:'active',duration:60,buffer:10,online_booking:1,active:1,working_days:['1','2','3','4','5','6'],starts_on:dateOnly(),taken_on:dateOnly(),due_on:dateOnly(),...defaults,...record};
        if(module==='appointments'&&!record.id)values.status='confirmed';if(module==='tasks'&&!record.id)values.status='open';if(module==='treatment_records'&&!record.id)values.status='draft';if(module==='waitlist'&&!record.id)values.status='waiting';
        openDialog(`${record.id?'Edit':'New'} ${d.title.toLowerCase()}`,`<form id="record-form"><div class="form-error" role="alert"></div><div class="form-grid">${Object.entries(d.fields).map(([key,f])=>fieldHtml(key,module==='users'&&key==='password'&&!record.id?{...f,label:'Password (at least 12 characters)',rules:'required|string|min:12'}:f,values[key])).join('')}</div>${module==='consents'?'<p class="form-hint">The exact form text and version are stored with this acknowledgement. Record only an acknowledgement actually given by the client.</p>':''}${module==='appointments'?'<p class="form-hint">Availability includes working hours, breaks, practitioner, client, room and device conflicts. Completing a visit requires a finalized treatment record and any required consent.</p>':''}${formFooter()}</form>`);
        const form=$('#record-form'),requestId=crypto.randomUUID();form.querySelector('[type=submit]').disabled=true;
        await Promise.all(Object.entries(d.fields).filter(([,f])=>f.source).map(([key])=>fillReference(module,key,values[key])));
        form.querySelectorAll('[data-reference]').forEach(el=>{let timer;el.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>fillReference(module,el.dataset.reference,Array.from($(`#field-${el.dataset.reference}`).selectedOptions).map(o=>o.value),el.value).catch(e=>toast(e.message,true)),300);});});
        if(module==='appointments')await linkBookingForm(values);
        form.addEventListener('submit',async event=>{
            event.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;form.querySelector('.form-error').textContent='';
            try {
                const data=new FormData(form);Object.entries(d.fields).forEach(([key,f])=>{if(f.type==='checkbox')data.set(key,form.elements[key].checked?'1':'0');if(['multiselect','multireference'].includes(f.type)){const vals=Array.from(form.elements[key].selectedOptions).map(o=>o.value);data.delete(key);vals.forEach(v=>data.append(key+'[]',v));}});
                data.set('request_id',requestId);if(record.id)data.set('_method','PUT');
                const result=await api(`modules/${module}${record.id?'/'+record.id:''}`,{method:'POST',body:data});closeDialog();toast(result.message);bookingOptions=null;if(['menu_items','users'].includes(module))await refreshBootstrap();await reloadCurrent();
            }catch(error){form.querySelector('.form-error').textContent=error.message;submit.disabled=false;}
        });
        form.dataset.ready='true';form.querySelector('[type=submit]').disabled=false;
    }
    async function getBookingOptions(){return bookingOptions ||= await api('appointments/options');}
    async function linkBookingForm(values) {
        const options=await getBookingOptions(),service=$('#field-service_id'),staff=$('#field-staff_id'),client=$('#field-client_id'),packages=$('#field-client_package_id');
        const replace=(el,items,selected,blank=true)=>{el.innerHTML=(blank?'<option value="">None</option>':'')+items.map(x=>`<option value="${x.id}" ${String(selected)===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('');};
        replace(service,options.services,values.service_id,false);
        function update(serviceChanged=false){const s=options.services.find(x=>x.id===Number(service.value));if(!s)return;const previous=staff.value||values.staff_id;replace(staff,options.staff.filter(x=>options.assignments.some(a=>a.service_id===s.id&&a.staff_id===x.id)),previous,false);if(serviceChanged){$('#field-duration').value=s.duration;$('#field-buffer').value=s.buffer;$('#field-room_id').value=s.required_room_id||'';$('#field-device_id').value=s.required_device_id||'';}replace(packages,options.packages.filter(x=>x.client_id===Number(client.value)&&x.service_id===s.id).map(x=>({id:x.id,name:`${x.name} · ${x.sessions_total-x.sessions_used} left · expires ${x.expires_on}`})),packages.value||values.client_package_id);}
        replace($('#field-room_id'),options.resources.filter(x=>x.type!=='device'),values.room_id);replace($('#field-device_id'),options.resources.filter(x=>x.type==='device'),values.device_id);
        service.addEventListener('change',()=>update(true));client.addEventListener('change',()=>update());update(!values.id);
        formLimitSearch();
        function formLimitSearch(){['service_id','staff_id','room_id','device_id','client_package_id'].forEach(key=>{const input=$(`[data-reference="${key}"]`);if(input)input.hidden=true;});}
    }
    async function calendarPage(run) {
        const options=await getBookingOptions();if(run!==navigationId)return;
        $('#content').innerHTML=heading('Make space for great care.','Practitioners, rooms and devices. One connected calendar.',newButton('appointments','New appointment'))+subnav('appointments')+`<div class="calendar-filters"><select class="form-control" id="calendar-staff" aria-label="Filter practitioner"><option value="">All practitioners</option>${options.staff.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><select class="form-control" id="calendar-status" aria-label="Filter status"><option value="">All statuses</option>${['confirmed','checked_in','completed','cancelled','no_show'].map(s=>`<option>${s}</option>`).join('')}</select><span class="form-hint">${esc(boot.settings.timezone)} · Click a slot to book</span></div><section class="panel calendar-panel"><div id="calendar"></div></section>`;
        calendar=new FullCalendar.Calendar($('#calendar'),{plugins:['dayGrid','timeGrid','list','interaction'],defaultView:innerWidth<760?'listWeek':'timeGridWeek',header:{left:'prev,next today',center:'title',right:'dayGridMonth,timeGridWeek,timeGridDay,listWeek'},height:'auto',minTime:'07:00:00',maxTime:'21:00:00',allDaySlot:false,nowIndicator:true,firstDay:1,selectable:!!boot.modules.appointments.can_create,editable:false,
            events:async(info,success,failure)=>{try{const result=await api(`modules/appointments?per_page=500&from=${encodeURIComponent(info.startStr)}&to=${encodeURIComponent(info.endStr)}&staff_id=${$('#calendar-staff').value}&status=${$('#calendar-status').value}`);rows=result.rows;success(rows.map(a=>({id:a.id,title:`${a.client_id_label} · ${a.service_id_label}`,start:a.starts_at.replace(' ','T'),end:a.ends_at.replace(' ','T'),backgroundColor:options.staff.find(s=>s.id===a.staff_id)?.color||'#739d92',extendedProps:{record:a}})));$('#calendar').dataset.ready='true';if(result.total>500)toast('More than 500 appointments: narrow the date range or practitioner filter.');}catch(e){failure(e);toast(e.message,true);}},
            select:info=>{editRecord('appointments',{}, {starts_at:info.startStr.slice(0,16),staff_id:$('#calendar-staff').value}).catch(e=>toast(e.message,true));},
            eventClick:info=>{const r=info.event.extendedProps.record;bookingDetail(r);}
        });calendar.render();$('#calendar-staff').addEventListener('change',()=>calendar.refetchEvents());$('#calendar-status').addEventListener('change',()=>calendar.refetchEvents());
    }
    function bookingDetail(record){openDialog('Appointment #'+record.id,detailHtml(record,boot.modules.appointments)+`<div class="form-actions">${boot.modules.treatment_records?.can_create?`<button class="btn btn-light" data-document="${record.id}">Treatment record</button>`:''}${boot.modules.form_templates?.can_create?`<button class="btn btn-light" data-consent="${record.id}" data-client-id="${record.client_id}">Consent</button>`:''}${boot.modules.appointments.can_edit&&!['completed','cancelled','no_show'].includes(record.status)?`<button class="btn btn-primary" data-edit-booking="${record.id}">Edit appointment</button>`:''}</div>`);}
    async function reloadCurrent(){if(calendar){calendar.refetchEvents();return;}if(current==='dashboard')return dashboard(navigationId);if(current==='roles')return rolesPage(navigationId);return listPage(navigationId);}
    async function rolesPage(run){const data=await api('roles');if(run!==navigationId)return;$('#content').innerHTML=heading('Access, on your terms.','Create user types and choose exactly what each team can see and do.',newButton('roles','Create role'))+`<div class="role-grid">${data.roles.map(r=>`<article class="panel role-card"><span class="stat-icon">${icon(r.is_owner?'crown':'user-shield')}</span><h3>${esc(r.name)}</h3><p>${esc(r.description||'Custom clinic role')}</p><span class="role-count">${r.is_owner?'Full workspace access':r.permissions.length+' permissions assigned'}</span><button class="btn btn-light" data-role="${r.id}">${r.is_owner?'View permissions':'Manage permissions'} →</button></article>`).join('')}</div>`;rows=data.roles;}
    async function roleForm(role={}){const readOnly=!!role.is_owner||!(role.id?boot.modules.roles.can_edit:boot.modules.roles.can_create);const data=await api('roles'),selected=new Set((role.permissions||[]).map(x=>x.id));openDialog(role.id?'Role · '+role.name:'Create a user type',`<form id="role-form"><div class="form-error" role="alert"></div><div class="form-grid">${fieldHtml('name',{label:'Role name',type:'text',rules:'required'},role.name)}${fieldHtml('description',{label:'Description',type:'text',rules:''},role.description)}</div><p class="form-hint">View permissions control the sidebar. Create and edit permissions control the corresponding server actions. The owner role is protected.</p><div class="table-responsive"><table class="table permission-table"><thead><tr><th>Module</th><th>View</th><th>Create</th><th>Edit</th></tr></thead><tbody>${[...new Set(data.permissions.map(p=>p.module))].map(m=>`<tr><td>${esc(boot.modules[m]?.title||title(m))}</td>${['view','create','edit'].map(a=>{const p=data.permissions.find(p=>p.module===m&&p.action===a);return `<td><input type="checkbox" name="permissions" value="${p.id}" aria-label="${esc(a+' '+m)}" ${role.is_owner||selected.has(p.id)?'checked':''} ${readOnly?'disabled':''}></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${readOnly?'<div class="form-actions"><button type="button" class="btn btn-light" data-close>Close</button></div>':formFooter('Save role')}</form>`);$('#role-form').addEventListener('submit',async e=>{e.preventDefault();if(readOnly)return;const f=e.currentTarget,button=f.querySelector('[type=submit]');button.disabled=true;try{const r=await api('roles'+(role.id?'/'+role.id:''),{method:role.id?'PUT':'POST',body:JSON.stringify({name:f.elements.name.value,description:f.elements.description.value,permissions:Array.from(f.querySelectorAll('[name=permissions]:checked')).map(x=>Number(x.value))})});closeDialog();toast(r.message);await refreshBootstrap();await rolesPage(navigationId);}catch(err){f.querySelector('.form-error').textContent=err.message;button.disabled=false;}});}
    async function settingsPage(run){const data=await api('settings');if(run!==navigationId)return;const definitions={clinic_name:{label:'Clinic name',type:'text'},location:{label:'Location',type:'text'},currency:{label:'Currency',type:'select',options:['CAD','USD','GBP','PKR','AED','EUR']},timezone:{label:'Timezone (IANA)',type:'text'},tax_percent:{label:'Default tax (%)',type:'number'},email:{label:'Clinic email',type:'email'},phone:{label:'Phone',type:'text'},booking_notice_hours:{label:'Online booking notice (hours)',type:'number'},reminder_hours:{label:'Reminder window (hours)',type:'number'}};$('#content').innerHTML=heading('A workspace that fits your clinic.','Configure business details and the rules behind every visit.')+`<section class="panel"><div class="panel-body"><form id="settings-form"><div class="form-error" role="alert"></div><div class="form-grid">${Object.entries(definitions).map(([k,f])=>fieldHtml(k,{...f,rules:['email','phone'].includes(k)?'':'required'},data[k])).join('')}</div><div class="form-actions"><button class="btn btn-primary">Save settings →</button></div></form></div></section>`;const settingsForm=$('#settings-form');window.ClinicTheme.mount(settingsForm,data,boot);if(!boot.permissions.settings_edit){settingsForm.querySelectorAll('input,select,button').forEach(el=>el.disabled=true);settingsForm.querySelector('.form-actions').innerHTML='<span class="muted">Your role has read-only access to settings.</span>';}settingsForm.addEventListener('submit',async e=>{e.preventDefault();if(!boot.permissions.settings_edit)return;const f=e.currentTarget;try{const r=await api('settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(f)))});await refreshBootstrap();toast(r.message);}catch(err){f.querySelector('.form-error').textContent=err.message;}});}
    async function reportsPage(run){$('#content').innerHTML=heading('A clearer view of your business.','Live results from appointments, invoices, payments and inventory.')+`<form id="report-filter" class="toolbar"><div class="calendar-filters"><label>From <input class="form-control" type="date" name="from" value="${dateOnly(new Date(new Date().getFullYear(),new Date().getMonth(),1))}" required></label><label>To <input class="form-control" type="date" name="to" value="${dateOnly()}" required></label><button class="btn btn-primary" type="submit">Update report</button></div><a id="report-export" class="btn btn-light" href="#">${icon('download')} Export CSV</a></form><div id="report-content"></div>`;const load=async()=>{const params=new URLSearchParams(new FormData($('#report-filter')));const d=await api('reports?'+params);if(run!==navigationId)return;$('#report-export').href='/api/reports?'+params+'&export=1';let html='<div class="stats-grid">';for(const key of ['invoiced_cents','collected_cents','outstanding_cents','package_redemptions']){if(key in d)html+=`<article class="stat-card"><div class="stat-top">${esc(title(key.replace('_cents','')))}</div><div class="stat-value">${key.endsWith('_cents')?money(d[key]):d[key]}</div><div class="stat-foot">${key==='outstanding_cents'?'Current balance across all dates':'Selected reporting period'}</div></article>`;}html+='</div><div class="report-grid">';for(const key of ['currency_totals','branches','statuses','practitioners','services','payment_methods','stock']){if(d[key])html+=panel(title(key),'From your connected clinic records.',simpleTable(key==='branches'?d[key].map(({branch_id,timezone,...row})=>row):d[key]));}$('#report-content').innerHTML=html+'</div>';};$('#report-filter').addEventListener('submit',e=>{e.preventDefault();load().catch(err=>toast(err.message,true));});await load();}
    function simpleTable(data){if(!data.length)return empty('Nothing to report yet.','Records appear here as your team works.');const keys=Object.keys(data[0]);return `<div class="table-responsive"><table class="table"><thead><tr>${keys.map(k=>`<th>${esc(title(k.replace('_cents','')))}</th>`).join('')}</tr></thead><tbody>${data.map(row=>`<tr>${keys.map(k=>`<td>${display(row,k)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
    function aggregateDashboard(d){
        const card=(label,value,note)=>`<article class="stat-card"><div class="stat-top">${esc(label)}</div><div class="stat-value">${esc(value)}</div><div class="stat-foot">${esc(note)}</div></article>`;
        $('#content').innerHTML=heading('Every branch. One clear view.','Organization-wide totals with each branch’s data kept separate.',`<button class="btn btn-primary" data-route="branches">${icon('building')} Manage branches</button>`)+`<div class="stats-grid">${card('Active branches',d.branches.length,'Within your organization')}${card('Appointments today',d.stats.appointments,'Using each branch’s local day')}${card('Active clients',d.stats.clients,'Branch profiles, not deduplicated people')}${card('Completed visits',d.stats.completed,'Across all active branches')}</div>`+panel('Financial overview','Currencies are reported separately; no exchange-rate assumptions.',simpleTable(d.currency_totals))+panel('Branch performance','Choose a branch in the sidebar to work with its records.',simpleTable(d.branches.map(({branch_id,timezone,...row})=>row)));
    }
    let organizationData;
    async function branchesPage(run){
        organizationData=await api('organization');if(run!==navigationId)return;
        $('#content').innerHTML=heading('Your organization, connected.',organizationData.organization.name+' · Independent branches with shared oversight.',`<button class="btn btn-light" id="rename-organization">Rename organization</button><button class="btn btn-primary" id="add-branch">+ Add branch</button>`)+`<div class="role-grid">${organizationData.branches.map(b=>`<article class="panel role-card"><span class="stat-icon">${icon('building')}</span><h3>${esc(b.name)}</h3><p>${esc(b.location)}<br>${esc(b.currency)} · ${esc(b.timezone)}</p><span class="role-count">${b.users} users · ${b.clients} clients · ${b.appointments} appointments</span>${badge(b.active?'active':'inactive')}<div class="heading-actions" style="margin-top:16px"><button class="btn btn-light" data-edit-branch="${b.id}">Edit</button>${b.active?`<button class="btn btn-primary" data-switch-branch="${b.id}">Open branch →</button>`:''}</div><p class="form-hint" style="margin-top:15px"><a target="_blank" rel="noopener" href="/book/${esc(b.slug)}">Branch booking page ↗</a></p></article>`).join('')}</div>`+panel('Branch memberships','An account can hold a different role at each assigned branch.',simpleTable(organizationData.memberships.map(m=>({user:m.user,email:m.email,branch:m.branch,role:m.role,status:m.active?'active':'inactive'}))),'<button class="btn btn-light btn-sm" id="assign-membership">Assign / change access</button>');
        $('#add-branch').onclick=()=>branchForm();$('#assign-membership').onclick=()=>membershipForm();$('#rename-organization').onclick=()=>organizationForm();
    }
    async function switchBranch(id){closeDialog();await api('branch-selection',{method:'POST',body:JSON.stringify({branch_id:id})});bookingOptions=null;await refreshBootstrap();await navigate(boot.permissions.dashboard?'dashboard':(Object.keys(boot.modules)[0]||'unavailable'));toast('Branch workspace switched.');}
    function branchForm(branch={}){
        const fields={name:{label:'Branch name',type:'text',rules:'required'},slug:{label:'Unique booking URL slug',type:'text',rules:'required'},location:{label:'Location',type:'text',rules:'required'},currency:{label:'Currency',type:'select',options:['CAD','USD','GBP','PKR','AED','EUR'],rules:'required'},timezone:{label:'Timezone (IANA)',type:'text',rules:'required'},active:{label:'Active branch',type:'checkbox',rules:'boolean'}};
        const values={currency:boot.organization.currency,timezone:boot.organization.timezone,active:true,...branch};
        openDialog(branch.id?'Edit branch':'Create a branch',`<form id="branch-form"><div class="form-error" role="alert"></div><div class="form-grid">${Object.entries(fields).map(([k,f])=>fieldHtml(k,f,values[k])).join('')}</div><p class="form-hint">A new branch starts with its own roles, sidebar and payment methods. Add its team, services and clients after switching to it.</p>${formFooter('Save branch')}</form>`);
        $('#branch-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{const data=Object.fromEntries(new FormData(f));data.active=f.elements.active.checked;const r=await api('organization/branches'+(branch.id?'/'+branch.id:''),{method:branch.id?'PUT':'POST',body:JSON.stringify(data)});closeDialog();toast(r.message);await refreshBootstrap();await branchesPage(navigationId);}catch(err){f.querySelector('.form-error').textContent=err.message;b.disabled=false;}};
    }
    function organizationForm(){openDialog('Organization details',`<form id="organization-form"><div class="form-error" role="alert"></div>${fieldHtml('name',{label:'Organization name',type:'text',rules:'required'},organizationData.organization.name)}${formFooter('Save name')}</form>`);$('#organization-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const r=await api('organization',{method:'PUT',body:JSON.stringify({name:f.elements.name.value})});closeDialog();toast(r.message);await refreshBootstrap();await branchesPage(navigationId);}catch(err){f.querySelector('.form-error').textContent=err.message;}};}
    async function membershipForm(){
        const users=organizationData.users.filter(u=>!u.is_org_owner);
        openDialog('Assign branch access',`<form id="membership-form"><div class="form-error" role="alert"></div><div class="form-grid"><label>User<select name="user_id" class="form-control" required>${users.map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(u.email)}</option>`).join('')}</select></label><label>Branch<select name="branch_id" class="form-control">${organizationData.branches.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></label><label>Role in this branch<select name="role_id" class="form-control" required></select></label><label class="check-label"><input type="checkbox" name="active" checked> Active membership</label></div><p class="form-hint">Create new accounts from Users inside a branch. Use this form to grant an existing account access to another branch, or update its branch role.</p>${formFooter('Save membership')}</form>`);
        const f=$('#membership-form');const load=async()=>{const roles=await api(`organization/branches/${f.elements.branch_id.value}/roles`);f.elements.role_id.innerHTML=roles.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');const existing=organizationData.memberships.find(m=>m.branch_id===Number(f.elements.branch_id.value)&&m.user_id===Number(f.elements.user_id.value));if(existing){f.elements.role_id.value=existing.role_id;f.elements.active.checked=!!existing.active;}else f.elements.active.checked=true;};f.elements.branch_id.onchange=()=>load().catch(e=>toast(e.message,true));f.elements.user_id.onchange=f.elements.branch_id.onchange;await load();
        f.onsubmit=async e=>{e.preventDefault();const button=f.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(f));data.active=f.elements.active.checked;const r=await api('organization/memberships',{method:'POST',body:JSON.stringify(data)});closeDialog();toast(r.message);await branchesPage(navigationId);}catch(err){f.querySelector('.form-error').textContent=err.message;button.disabled=false;}};
    }
    async function clientProfile(id){const data=await api(`clients/${id}/profile`);let html=detailHtml(data.client,boot.modules.clients);if('reward_points'in data)html+=`<div class="note-banner">${data.reward_points} available reward points</div>`;for(const [k,v]of Object.entries(data)){if(!Array.isArray(v))continue;const keys=({appointments:['id','starts_at','status'],invoices:['id','number','total_cents'],client_packages:['id','sessions_total','sessions_used','expires_on'],memberships:['id','expires_on','status'],tasks:['title','due_on','status'],photos:['id','caption','stage'],consents:['id','signed_name','signed_at'],treatment_records:['id','assessment','status']}[k]||[]);html+=`<h3 class="section-label">${esc(title(k))}</h3>`+simpleTable(v.map(r=>Object.fromEntries(keys.map(key=>[key,r[key]]))));}openDialog(data.client.name,html);}
    async function invoiceForm(){const o=await api('billing/options');openDialog('Create an invoice',`<form id="invoice-form"><div class="form-error" role="alert"></div><div class="form-grid"><label>Client<select name="client_id" class="form-control" required>${o.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Due date<input name="due_on" class="form-control" type="date" value="${dateOnly()}" required></label><label class="full">Appointment (optional)<select name="appointment_id" class="form-control"><option value="">No appointment</option></select></label></div><h3 class="section-label">Invoice items</h3><div id="invoice-lines"></div><button class="btn btn-light btn-sm" type="button" id="add-invoice-line">+ Add item</button><div class="form-grid" style="margin-top:20px"><label>Discount<input class="form-control" name="discount" type="number" step=".01" min="0" value="0"></label><label>Notes<input class="form-control" name="notes"></label></div><div id="invoice-total" class="invoice-summary"></div><p class="form-hint">Invoices are immutable once issued. Product stock is deducted and package/membership entitlements are created when the invoice is issued; payment balances are tracked separately.</p>${formFooter('Issue invoice')}</form>`);
        const form=$('#invoice-form'),requestId=crypto.randomUUID();const catalogs={service:o.services,product:o.products,package:o.packages,membership:o.membership_plans};
        function total(){let cents=Number(o.appointments.find(a=>a.id===Number(form.elements.appointment_id.value))?.price_cents||0);form.querySelectorAll('.invoice-line').forEach(line=>{const type=line.querySelector('.item-type').value;const item=catalogs[type].find(x=>x.id===Number(line.querySelector('.item-id').value));cents+=(item?.price_cents||0)*Number(line.querySelector('.item-quantity').value||0);});const discounted=Math.max(0,cents-Math.round(Number(form.elements.discount.value||0)*100));$('#invoice-total').textContent=`Subtotal ${money(cents)} · Tax ${boot.settings.tax_percent}% · Total ${money(discounted+Math.round(discounted*Number(boot.settings.tax_percent)/100))}`;}
        function appointmentOptions(){form.elements.appointment_id.innerHTML='<option value="">No appointment</option>'+o.appointments.filter(a=>a.client_id===Number(form.elements.client_id.value)).map(a=>`<option value="${a.id}">#${a.id} · ${esc(a.starts_at)} · ${money(a.price_cents)}</option>`).join('');total();}
        function addLine(){const line=document.createElement('div');line.className='invoice-line';line.innerHTML=`<select class="form-control item-type" aria-label="Item type">${Object.keys(catalogs).map(k=>`<option value="${k}">${title(k)}</option>`).join('')}</select><select class="form-control item-id" aria-label="Item" required></select><input class="form-control item-quantity" type="number" min="1" max="100" value="1" aria-label="Quantity" required><button class="icon-button" type="button" aria-label="Remove item">×</button>`;const populate=()=>{line.querySelector('.item-id').innerHTML=catalogs[line.querySelector('.item-type').value].map(i=>`<option value="${i.id}">${esc(i.name)} · ${money(i.price_cents)}</option>`).join('');total();};line.querySelector('.item-type').addEventListener('change',populate);line.querySelector('button').onclick=()=>{line.remove();total();};$('#invoice-lines').append(line);populate();}
        $('#add-invoice-line').onclick=addLine;form.elements.client_id.onchange=appointmentOptions;form.addEventListener('input',total);form.addEventListener('change',total);appointmentOptions();
        form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{const payload=Object.fromEntries(new FormData(form));payload.appointment_id=payload.appointment_id||null;payload.lines=Array.from(form.querySelectorAll('.invoice-line')).map(l=>({type:l.querySelector('.item-type').value,item_id:Number(l.querySelector('.item-id').value),quantity:Number(l.querySelector('.item-quantity').value)}));payload.request_id=requestId;const r=await api('billing/invoices',{method:'POST',body:JSON.stringify(payload)});closeDialog();toast(r.message);await reloadCurrent();}catch(err){form.querySelector('.form-error').textContent=err.message;button.disabled=false;}};
    }
    async function invoiceDetail(id){const d=await api(`billing/invoices/${id}`);const paid=d.payments.reduce((s,p)=>s+p.amount_cents,0);openDialog(d.invoice.number,`<h3>${esc(boot.settings.clinic_name)}</h3><p class="muted">${esc(d.client.name)} · Due ${esc(d.invoice.due_on)}</p>${simpleTable(d.lines.map(l=>({description:l.description,quantity:l.quantity,unit_price_cents:l.unit_price_cents,total_cents:l.total_cents})))}<div class="invoice-summary">Subtotal ${money(d.invoice.subtotal_cents)}<br>Discount ${money(d.invoice.discount_cents)} · Tax ${money(d.invoice.tax_cents)}<br><strong>Total ${money(d.invoice.total_cents)} · Balance ${money(d.invoice.total_cents-paid)}</strong></div><h3 class="section-label">Payment history</h3>${simpleTable(d.payments.map(p=>({id:p.id,method:p.method,amount_cents:p.amount_cents,reference:p.reference,created_at:p.created_at})))}<div class="form-actions"><button class="btn btn-light" id="print-invoice">Print invoice</button>${boot.modules.invoices.can_edit?`<button class="btn btn-primary" data-payment="${id}">Record payment / refund</button>`:''}</div>`);$('#print-invoice').onclick=()=>window.print();}
    async function paymentForm(id){const [o,d]=await Promise.all([api('billing/options'),api(`billing/invoices/${id}`)]);const balance=d.invoice.total_cents-d.payments.reduce((s,p)=>s+p.amount_cents,0),requestId=crypto.randomUUID();openDialog('Record cash payment · '+d.invoice.number,`<form id="payment-form"><div class="form-error" role="alert"></div><div class="note-banner">Balance ${money(balance)}. Cash only. Record cash received or a cash refund against the original receipt.</div><div class="form-grid"><label>Amount<input class="form-control" name="amount" type="number" min=".01" step=".01" value="${Math.max(0,balance)/100}" required></label><label>Payment method<select class="form-control" name="payment_method_id">${o.payment_methods.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>Reference<input name="reference" class="form-control"></label><label>Transaction<select name="refund_of" class="form-control"><option value="">Receive payment</option>${d.payments.filter(p=>p.amount_cents>0).map(p=>`<option value="${p.id}">Refund payment #${p.id} · ${money(p.amount_cents)}</option>`).join('')}</select></label></div>${formFooter('Record transaction')}</form>`);$('#payment-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,button=f.querySelector('[type=submit]');button.disabled=true;try{const payload=Object.fromEntries(new FormData(f));payload.refund_of=payload.refund_of||null;payload.request_id=requestId;const r=await api(`billing/invoices/${id}/payments`,{method:'POST',body:JSON.stringify(payload)});closeDialog();toast(r.message);await reloadCurrent();}catch(err){f.querySelector('.form-error').textContent=err.message;button.disabled=false;}};}
    document.addEventListener('click',async event=>{
        const target=event.target.closest('button,a');if(!target)return;
        try {
            if(target.dataset.route){event.preventDefault();closeDialog();await navigate(target.dataset.route);}
            else if(target.dataset.expand){const el=document.getElementById(target.dataset.expand);el.hidden=!el.hidden;target.setAttribute('aria-expanded',String(!el.hidden));}
            else if(target.hasAttribute('data-close'))closeDialog();
            else if(target.dataset.new)await editRecord(target.dataset.new);
            else if(target.dataset.edit)await editRecord(current,rows.find(r=>r.id===Number(target.dataset.edit)));
            else if(target.dataset.detail){const r=rows.find(r=>r.id===Number(target.dataset.detail));openDialog(boot.modules[current].title,detailHtml(r,boot.modules[current])+(current==='photos'?`<a class="btn btn-light" href="/api/photos/${r.id}/file" target="_blank" rel="noopener">Open private file ↗</a>`:''));}
            else if(target.dataset.page){page=Number(target.dataset.page);await loadRows();}
            else if(target.dataset.role)await roleForm(rows.find(r=>r.id===Number(target.dataset.role)));
            else if(target.dataset.booking)bookingDetail(rows.find(r=>r.id===Number(target.dataset.booking)));
            else if(target.dataset.editBooking)await editRecord('appointments',rows.find(r=>r.id===Number(target.dataset.editBooking)));
            else if(target.dataset.document)await editRecord('treatment_records',{}, {appointment_id:target.dataset.document});
            else if(target.dataset.consent)await editRecord('consents',{}, {appointment_id:target.dataset.consent,client_id:target.dataset.clientId});
            else if(target.dataset.invoice)await invoiceDetail(target.dataset.invoice);
            else if(target.dataset.payment)await paymentForm(target.dataset.payment);
            else if(target.dataset.client)await clientProfile(target.dataset.client);
            else if(target.dataset.prepare){const r=await api(`campaigns/${target.dataset.prepare}/prepare`,{method:'POST'});toast(r.message);await reloadCurrent();}
            else if(target.dataset.convert){const r=await api(`leads/${target.dataset.convert}/convert`,{method:'POST'});toast(r.message);await reloadCurrent();}
            else if(target.dataset.waitlist){const r=rows.find(x=>x.id===Number(target.dataset.waitlist));await editRecord('appointments',{}, {client_id:r.client_id,service_id:r.service_id,waitlist_id:r.id,starts_at:r.preferred_date+'T09:00',notes:r.notes});}
            else if(target.dataset.editBranch)branchForm(organizationData.branches.find(b=>b.id===Number(target.dataset.editBranch)));
            else if(target.dataset.switchBranch)await switchBranch(target.dataset.switchBranch);
        }catch(error){toast(error.message,true);}
    });
    let searchTimer;document.addEventListener('input',event=>{if(event.target.id==='record-search'){clearTimeout(searchTimer);search=event.target.value;page=1;searchTimer=setTimeout(()=>loadRows().catch(e=>toast(e.message,true)),300);}});
    $('#close-editor').onclick=closeDialog;$('#menu-toggle').onclick=()=>document.body.classList.toggle('sidebar-open');$('#sidebar-scrim').onclick=()=>document.body.classList.remove('sidebar-open');
    $('#branch-selector').addEventListener('change',e=>switchBranch(e.target.value).catch(err=>{toast(err.message,true);$('#branch-selector').value=String(boot.selected_branch);}));
    $('#module-search').addEventListener('input',e=>{const term=e.target.value.toLowerCase();document.querySelectorAll('#navigation .nav-item').forEach(el=>{el.hidden=!!term&&!el.textContent.toLowerCase().includes(term);});if(term)document.querySelectorAll('.nav-children').forEach(el=>el.hidden=false);});
    document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#module-search').focus();}});
    window.addEventListener('popstate',()=>navigate(location.pathname.split('/')[2]||'dashboard',false));
    refreshBootstrap().then(()=>{const first=items=>{for(const item of items){if(item.module)return item.module;const nested=first(item.children);if(nested)return nested;}};const requested=location.pathname.split('/')[2];return navigate(requested||(boot.permissions.dashboard?'dashboard':first(boot.menu)||'unavailable'),false);}).catch(e=>{$('#content').innerHTML=empty('Workspace unavailable',e.message);});
})();
